#include <bits/stdc++.h>
using namespace std;

long long compute_value(long long n) {
    static unordered_map<long long, long long> memo;
    if (memo.count(n)) return memo[n];
    if (n <= 11) return min(n, 2 + (11 - n));
    long long base = 1, depth = 1;
    while (base <= n) {
        base = base * 10 + 1;
        depth++;
    }
    long long limit = base / 10;
    if (base > 2 * n) {
        long long times = n / limit;
        long long rem = n % limit;
        long long optionA = compute_value(base - n) + depth;
        long long optionB = times * (depth - 1) + compute_value(rem);
        return memo[n] = min(optionA, optionB);
    } else {
        long long times = n / limit;
        long long rem = n % limit;
        long long optionA = compute_value(base - n) + depth;
        long long optionB = times * (depth - 1) + compute_value(rem);
        return memo[n] = min(optionA, optionB);
    }
}

int main() {
    long long num;
    cin >> num;
    cout << compute_value(num);
    return 0;
}
